import os
import sys
directory = sys.argv[1]
try:
    for entry in sorted(os.scandir(directory), key=lambda entry: entry.name):
        if entry.is_file():
            print(f"{entry.name}: {entry.stat().st_size} bytes")
except FileNotFoundError:
    print(f"Directory not found: {directory}")
